function maxRectangleArea(nums) {
  const n = nums.length;
  const left = Array(n).fill(0);
  const right = Array(n).fill(n - 1);

  const stack = [];

  // Find the previous smaller element for each index
  for (let i = 0; i < n; i++) {
    while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) {
      stack.pop();
    }
    if (stack.length) left[i] = stack[stack.length - 1] + 1;
    stack.push(i);
  }

  stack.length = 0; // Clear the stack

  // Find the next smaller element for each index
  for (let i = n - 1; i >= 0; i--) {
    while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) {
      stack.pop();
    }
    if (stack.length) right[i] = stack[stack.length - 1] - 1;
    stack.push(i);
  }

  let maxArea = 0;
  for (let i = 0; i < n; i++) {
    const width = right[i] - left[i] + 1;
    const area = width * nums[i];
    maxArea = Math.max(maxArea, area);
  }

  return maxArea;
}
